Object.assign(window.DYLEAN_DATA.files["Library/Init/LawfulBEqTactics.lean"],{"text":"/-\nCopyright (c) 2025 Lean FRO, LLC. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Joachim Breitner\n-/\n\nmodule\nprelude\npublic import Init.Core\nimport Init.Data.Bool\nimport Init.ByCases\nimport Init.Classical\n\npublic section\n\nnamespace DerivingHelpers\n\nmacro \"deriving_ReflEq_tactic\" : tactic => `(tactic|(\n  intro x\n  induction x\n  all_goals\n    simp only [BEq.refl, ↓reduceDIte, Bool.and_true, *, reduceBEq ,reduceCtorIdx]\n))\n\ntheorem and_true_curry {a b : Bool} {P : Prop}\n    (h : a → b → P) : (a && b) → P := by\n  rw [Bool.and_eq_true_iff]\n  intro h'\n  apply h h'.1 h'.2\n\n\ntheorem deriving_lawful_beq_helper_dep {x y : α} [BEq α] [ReflBEq α]\n    {t : (x == y) = true → Bool} {P : Prop}\n    (inst : (x == y) = true → x = y)\n    (k : (h : x = y) → t (h ▸ ReflBEq.rfl) = true → P) :\n    (if h : (x == y) then t h else false) = true → P := by\n  split\n  · exact k (inst ‹_›)\n  · nofun\n\ntheorem deriving_lawful_beq_helper_nd {x y : α} [BEq α] [ReflBEq α]\n    {P : Prop}\n    (inst : (x == y) = true → x = y)\n    (k : x = y → P) :\n    (x == y) = true → P :=\n  k ∘ inst\n\nend DerivingHelpers\n\nsyntax \"deriving_LawfulEq_tactic_step\" : tactic\nmacro_rules\n| `(tactic| deriving_LawfulEq_tactic_step) =>\n  `(tactic| fail \"deriving_LawfulEq_tactic_step failed\")\nmacro_rules\n| `(tactic| deriving_LawfulEq_tactic_step) =>\n  `(tactic| ( with_reducible change dite (_ == _) _ _ = true → _\n              refine DerivingHelpers.deriving_lawful_beq_helper_dep ?_ ?_\n              · solve | apply_assumption | simp | fail \"could not discharge eq_of_beq assumption\"\n              intro h\n              cases h\n              dsimp only\n    ))\nmacro_rules\n| `(tactic| deriving_LawfulEq_tactic_step) =>\n  `(tactic| ( with_reducible change (_ == _) = true → _\n              refine DerivingHelpers.deriving_lawful_beq_helper_nd ?_ ?_\n              · solve | apply_assumption | simp | fail \"could not discharge eq_of_beq assumption\"\n              intro h\n              subst h\n    ))\nmacro_rules\n| `(tactic| deriving_LawfulEq_tactic_step) =>\n  `(tactic| ( with_reducible change (_ == _ && _) = true → _\n              refine DerivingHelpers.and_true_curry ?_))\nmacro_rules\n| `(tactic| deriving_LawfulEq_tactic_step) =>\n  `(tactic| rfl)\nmacro_rules\n| `(tactic| deriving_LawfulEq_tactic_step) =>\n  `(tactic| intro _; trivial)\n\nmacro \"deriving_LawfulEq_tactic\" : tactic => `(tactic|(\n  intro x\n  induction x\n  all_goals\n    intro y\n    cases y\n    all_goals\n      simp only [reduceBEq, reduceCtorIdx]\n      repeat deriving_LawfulEq_tactic_step\n))\n","refs":[[17,33,17,39,"dfe60c6dc2a8",false],[24,8,24,22,"1c7fa73e8719",true],[24,30,24,34,"13bef7c8f748",false],[26,6,26,26,"fbf6ca9904d7",false],[28,13,28,14,"e5d4756c1075",false],[28,18,28,19,"e16eaafea41d",false],[31,50,31,53,"03195a368da8",false],[31,58,31,65,"393e7fc225a5",false],[32,20,32,24,"ef519a160226",false],[32,27,32,31,"13bef7c8f748",false],[33,23,33,27,"ef519a160226",false],[34,30,34,41,"a98f3f27762a",false],[34,45,34,49,"ef519a160226",false],[35,35,35,40,"e97ff9f8035d",false],[35,44,35,48,"ef519a160226",false],[40,8,40,37,"f742a3a9c87b",true],[40,49,40,52,"03195a368da8",false],[40,57,40,64,"393e7fc225a5",false],[42,23,42,27,"ef519a160226",false],[44,15,44,19,"ef519a160226",false],[49,41,49,47,"dfe60c6dc2a8",false],[81,35,81,41,"dfe60c6dc2a8",false]]});
